import{z as o,x as d,o as r,c as A,q as i,j as B,D as t,d as l,s,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"空间填充曲线","description":"","frontmatter":{"title":"空间填充曲线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/space-filling-curve.md","filePath":"cs/space-filling-curve.md","lastUpdated":1791063341000}'),p={name:"cs/space-filling-curve.md"};function c(m,e,u,b,f,h){const E=d("Mermaid");return r(),A("div",null,[e[2]||(e[2]=i('<h1 id="空间填充曲线" tabindex="-1">空间填充曲线 <a class="header-anchor" href="#空间填充曲线" aria-label="Permalink to &quot;空间填充曲线&quot;">​</a></h1><div class="epigraph"><p>用一条连续折线串起网格单元，使空间相邻尽量在一维上也相邻；B 树与缓存看见的是这个线性序。</p><footer>—— 据 Hilbert, Über die stetige Abbildung einer Linie auf ein Flächenstück, 1891；Morton, A Computer Oriented Geodetic Data Base, 1966；Samet 整理</footer></div><p><a href="/cs/quadtree-octree">上一课</a> 给出象限。外存与<a href="/cs/locality-principle">局部性</a> 要的是一维扫描序。<a href="/cs/r-tree">R 树</a> 插入也可按 Hilbert 值排序打包。本课不切立方体。缺口是空间填充曲线：Morton（Z 序）与 Hilbert，把坐标比特交错或按旋转状态机编号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二维键 \\((x,y)\\) 若先排 \\(x\\) 再排 \\(y\\)，竖条相邻在一维上可能很远。Z 序：交错 \\(x,y\\) 的比特，四叉块在序上成一段。Hilbert：更保持邻接，构造用状态与旋转。缺口是<strong>多维网格上的双射编号</strong>，使范围查询变成一维上若干段（不是一段）。</p><p><span class="marginnote">数字实例：\\(8\\times 8\\) 网格上，水平相邻的 \\((0,7)\\) 与 \\((1,7)\\)：行序编号是 7 和 15，差 8；Z 序把 \\(x,y\\) 的比特交错后分别编成 42 和 43，只差 1。「空间相邻在一维上也相邻」说的就是这个差值从 8 缩到 1。</span></p><p><span class="marginnote">Hilbert 1891 是分析学构造；数据库用离散网格版。Morton 1966 报告给出 Z 序。本课不把连续统曲线当作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Z 序：<code>code = interleave(x,y)</code>，比较即比较整数。范围查询：在 Z 空间上走，遇到出矩形则跳到下一可能码（clz 等技巧）。Hilbert：查表或迭代，编码稍贵，局部性通常更好。用于：把点排序后bulk-load R 树；缓存友好的矩阵分块遍历。</p>',9)),(r(),B(n,null,{default:t(()=>[s(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20XY%5B%22%E7%BD%91%E6%A0%BC%20(x%2C%20y)%22%5D%20--%3E%20CURVE%5B%22Z%20%E6%88%96%20Hilbert%20%E7%A0%81%22%5D%0A%20%20CURVE%20--%3E%20BTREE%5B%22%E4%B8%80%E7%BB%B4%20B%20%E6%A0%91%20%2F%20%E6%8E%92%E5%BA%8F%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"与 k-d / R：曲线不替代几何剪枝，只提供序。高维 Z 序仍交错，段数变多。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：Z 序像走之字形，每到块边界要「跳远」一格；Hilbert 像按规则不停左转右转的走迷宫笔法，笔尖尽量不抬起来——所以序号相邻的格子几乎总是空间相邻，邻接保持得更好。")],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"四叉树叶的 Z 序恰好是深度优先象限序的一种。Hilbert 在块边界更少「空间近、序号远」。不要声称任意形状查询都变成单区间——正交矩形在 Z 序上是 \\(O(\\sqrt{n})\\) 段一类现象，分析视查询而定。",-1)),(r(),B(n,null,{default:t(()=>[s(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RM%5B%22%E8%A1%8C%E5%BA%8F%EF%BC%9A%E5%85%88%20x%20%E5%90%8E%20y%22%5D%20--%3E%20BAD%5B%22%E7%AB%96%E7%9B%B4%E7%9B%B8%E9%82%BB%E7%9A%84%E6%A0%BC%E5%AD%90%E5%BA%8F%E5%8F%B7%E5%B7%AE%E4%B8%80%E6%95%B4%E8%A1%8C%22%5D%0A%20%20Z%5B%22Z%20%E5%BA%8F%EF%BC%9A%E6%AF%94%E7%89%B9%E4%BA%A4%E9%94%99%22%5D%20--%3E%20SEG%5B%22%E7%9B%B8%E9%82%BB%E5%9D%97%E5%BA%8F%E5%8F%B7%E8%81%9A%E6%8B%A2%E6%88%90%E6%AE%B5%22%5D%0A%20%20H%5B%22Hilbert%20%E5%BA%8F%EF%BC%9A%E5%B8%A6%E6%97%8B%E8%BD%AC%E7%BC%96%E5%8F%B7%22%5D%20--%3E%20GOOD%5B%22%E5%9D%97%E8%BE%B9%E7%95%8C%E8%B7%A8%E8%B6%8A%E6%9B%B4%E5%B0%91%22%5D%0A%20%20SEG%20--%3E%20RQ%5B%22%E8%8C%83%E5%9B%B4%E6%9F%A5%E8%AF%A2%20%3D%20%E4%B8%80%E7%BB%B4%E4%B8%8A%E8%8B%A5%E5%B9%B2%E6%AE%B5%22%5D%0A%20%20GOOD%20--%3E%20RQ%0A%20%20RQ%20--%3E%20Q%5B%22%E9%80%90%E6%AE%B5%E8%B5%B0%20B%20%E6%A0%91%EF%BC%8C%E4%B8%8D%E5%BF%85%E5%85%A8%E8%A1%A8%E6%89%AB%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=i('<p>这张图回答的是：三种线性化序对「空间邻接」的保持程度差在哪，以及范围查询为什么是「若干段」而不是一段。</p><p>平衡堆与空间课序在此结束。下一单元字符串：后缀数组把「所有后缀的字典序」收成一维，不再是几何曲线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写空间填充曲线上的并行划分全部论文。不进入金融订单簿。字符串后缀排序是另一课序。</p><p>后课默认：需要把网格线性化时用 Z/Hilbert。后缀排序从后缀数组开始。</p><p><span class="marginnote">常见误区：初学者容易以为矩形范围查询在 Z 序上是一段连续区间。实际上一个矩形会裂成若干段（数量与查询形状相关），实现要沿序跳跃式取段，而不是一次二分查完。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Z 序比特交错，Hilbert 更保邻接。</li><li>服务一维索引与 bulk-load，不是几何树的替代。</li><li>下一课程单元：后缀与哈希。</li><li>出处：Hilbert, 1891；Morton, 1966；Samet。</li></ul>',8))])}const _=o(p,[["render",c]]);export{C as __pageData,_ as default};
